import hashlib, json, os, pathlib, re, statistics, subprocess, time

root = pathlib.Path.cwd()
work = root / '_build/cache2546/metrics'
env = {k: v for k, v in os.environ.items() if not k.startswith(('VIBE_', 'NODE_'))}
env.update(VIBE_PREOPEN_DIR=str(root), VIBE_IMPORT_ABI='raw', VIBE_WASM_MEMORY_STATS='1')
report = {
    'issue': 2546,
    'baseline_commit': '084e7968c',
    'protocol': 'Three sequential alternating AB/BA pairs per compiler runtime. Full CLI source as input, RC output, a fresh cache per pair and variant, cold then warm in separate processes. Compiler/cache/output paths have equal lengths across variants. Checked-module, AST and codegen-body caches disabled; production module caches enabled. Node 24.21.0 through the repository wrapper (exnref, stack-size=4000; wasm-inlining flag unsupported). heap_ptr is allocator high-water; RSS is the process reading at completion, not peak RSS.',
    'compilers': {}, 'selfhost': [],
}
for runtime in ['bump', 'rc']:
    for side in 'ab':
        p = work / f'{side}-{runtime}.wasm'
        report['compilers'][f'{side}-{runtime}'] = {'sha256': hashlib.sha256(p.read_bytes()).hexdigest(), 'bytes': p.stat().st_size}
hashes = {}
for runtime in ['bump', 'rc']:
    for round in range(3):
        for side in ('ab' if round % 2 == 0 else 'ba'):
            folder = work / f'{runtime}-{round}-{side}'
            folder.mkdir()  # Refuse to reuse a previously warmed measurement.
            for temperature in ['cold', 'warm']:
                out = folder / 'out.wasm'
                extra = {'VIBE_FS_COMPILE': '1', 'VIBE_BACKEND': 'wasi', 'VIBE_RC': '1', 'VIBE_CHECKED_MODULE_CACHE': 'off', 'VIBE_EXPERIMENTAL_AST_CACHE': '0', 'VIBE_CODEGEN_BODY_CACHE': 'off', 'VIBE_WASM_NAMES': '0', 'VIBE_BUILD_CACHE_DIR': str(folder / 'cache')}
                args = ['bash', 'scripts/run_wasm_vibe_host_runner.sh', '--invoke', 'cli_main', str(work / f'{side}-{runtime}.wasm'), 'lib/@vibe/cli/entry.vibe', str(out), 'cli_main']
                out.unlink(missing_ok=True)
                start = time.monotonic()
                proc = subprocess.run(args, env={**env, **extra}, capture_output=True, text=True, timeout=300)
                wall = time.monotonic() - start
                (folder / f'{temperature}.log').write_text(proc.stdout + proc.stderr)
                proc.check_returncode()
                assert out.is_file() and out.stat().st_size > 0, proc
                stats = re.findall(r'\[wasm-memory\][^\n]+', proc.stderr)[-1]
                output_hash = hashlib.sha256(out.read_bytes()).hexdigest()
                assert not hashes or next(iter(hashes.values())) == output_hash, (side, hashes, output_hash)
                hashes[side] = output_hash
                row = {'runtime': runtime, 'round': round, 'variant': side, 'temperature': temperature, 'wall_s': wall, 'cache_files': sum(1 for f in (folder / 'cache').rglob('*') if f.is_file()), 'output_bytes': out.stat().st_size, 'output_sha256': output_hash, **{k: int(v) for k, v in re.findall(r'(pages|bytes|heap_ptr|rss)=([0-9]+)', stats)}}
                report['selfhost'].append(row)
                (root / '_build/cache2546/metrics.json').write_text(json.dumps(report, indent=2) + '\n')
                print(json.dumps(row), flush=True)
report['medians'] = []
for runtime in ['bump', 'rc']:
    for temperature in ['cold', 'warm']:
        row = {'runtime': runtime, 'temperature': temperature}
        for side in 'ab':
            observations = [r for r in report['selfhost'] if (r['runtime'], r['temperature'], r['variant']) == (runtime, temperature, side)]
            row[side] = {key: statistics.median(r[key] for r in observations) for key in ['wall_s', 'heap_ptr', 'rss', 'cache_files']}
        row['delta_percent'] = {key: (row['b'][key] / row['a'][key] - 1) * 100 for key in row['a']}
        report['medians'].append(row)
        print(json.dumps(row), flush=True)
report['measurement_harness'] = pathlib.Path(__file__).read_text()
(root / '_build/cache2546/metrics.json').write_text(json.dumps(report, indent=2) + '\n')
print('DONE', flush=True)

io.preload:
const fs = require('node:fs');
const path = require('node:path');
const root = path.resolve(process.env.VIBE_BUILD_CACHE_DIR);
const counts = {};
for (const name of ['existsSync', 'readFileSync', 'writeFileSync', 'renameSync']) {
  const original = fs[name];
  fs[name] = function (...args) {
    const file = args[name === 'renameSync' ? 1 : 0];
    if (typeof file === 'string' && path.resolve(file).startsWith(root + path.sep)) {
      counts[name] = (counts[name] || 0) + 1;
    }
    return original.apply(this, args);
  };
}
process.on('exit', () => process.stderr.write('[cache-io] ' + JSON.stringify(counts) + '\n'));
